package usecase;
import domain.entity.Contact; import domain.repository.IContactRepository; import java.util.*; import java.util.stream.Collectors;
public class ContactUseCase { private final IContactRepository r; public ContactUseCase(IContactRepository r){this.r=r;} public List<Contact> all(){return r.findAll();} public Contact add(String n,String p,String e){return r.save(n,p,e);} public boolean remove(int id){return r.deleteById(id);} public boolean update(int id,String n,String p,String e){Optional<Contact>c=r.findById(id);if(c.isEmpty())return false;c.get().update(n,p,e);return true;} public List<Contact> search(String k){String key=k.toLowerCase();return all().stream().filter(c->c.getName().toLowerCase().contains(key)||c.getPhone().contains(key)||c.getEmail().toLowerCase().contains(key)).collect(Collectors.toList());} }